"""One-shot recovery of verified assets; never constructs or runs a model."""
import argparse
import copy
import fcntl
import hashlib
import importlib.util
import json
import os
from pathlib import Path, PurePosixPath
import platform
import resource
import signal
import subprocess
import sys
import time
import urllib.parse


class RecoveryFailure(ValueError):
    """Fixed, non-secret diagnostic generated by this recovery implementation."""


def error_record(helper, error):
    if isinstance(error, RecoveryFailure):
        return {"type": type(error).__name__, "reason": str(error)}
    return helper.error_record(error)


def sha(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        while block := stream.read(1024 * 1024):
            digest.update(block)
    return digest.hexdigest()


def local(root, name):
    rel = PurePosixPath(name)
    if rel.is_absolute() or '..' in rel.parts or not rel.parts:
        raise RecoveryFailure('Unsafe relative path')
    path = Path(root)
    for part in rel.parts:
        path /= part
        if path.is_symlink():
            raise RecoveryFailure('Symlink is not a frozen input/output')
    return path


def inventory(root):
    root = Path(root)
    if root.is_symlink() or not root.is_dir():
        raise RecoveryFailure('Expected a real directory')
    result = {}
    for path in sorted(root.rglob('*')):
        if path.is_symlink() or not (path.is_file() or path.is_dir()):
            raise RecoveryFailure('Non-regular cache entry')
        if path.is_file():
            result[path.relative_to(root).as_posix()] = {'bytes': path.stat().st_size, 'sha256': sha(path)}
    return result


def bound_json(repo, reference):
    path = local(repo, reference['path'])
    if sha(path) != reference['sha256']:
        raise RecoveryFailure('Referenced frozen input changed: ' + reference['path'])
    return json.loads(path.read_text())


def load_context(repo, config):
    cfg = config['recovery']
    if cfg['schema_version'] != 1:
        raise RecoveryFailure('Unknown recovery schema')
    original = bound_json(repo, cfg['original_config'])['preparation']
    helper_path = local(repo, cfg['frozen_preparer']['path'])
    if sha(helper_path) != cfg['frozen_preparer']['sha256']:
        raise RecoveryFailure('Frozen preparer changed')
    spec = importlib.util.spec_from_file_location('_frozen_tapnext_preparer', helper_path)
    helper = importlib.util.module_from_spec(spec); spec.loader.exec_module(helper)
    helper.validate_config(original)
    evidence = {name: bound_json(repo, ref) for name, ref in cfg['evidence'].items()}
    return cfg, original, helper, evidence


def check_old_runtime(old, original, review):
    want = {**original['runtime']['old_init_sha256'], **review['old_markers_preserved']}
    for name, digest in want.items():
        if sha(local(old, name)) != digest:
            raise RecoveryFailure('Old runtime/marker changed: ' + name)
    return want


def verify_failed_cache(failed, cfg, original, evidence):
    """Verify the archived failure bytes, not reinterpret them as approval."""
    if inventory(failed) != evidence['cache_inventory']:
        raise RecoveryFailure('Failed cache differs from its immutable full inventory')
    receipt_path = local(failed, 'preparation-dependencies.json')
    if sha(receipt_path) != cfg['evidence']['failure_receipt']['sha256']:
        raise RecoveryFailure('Prior failure receipt changed')
    receipt = evidence['failure_receipt']; review = evidence['failure_review']
    if (receipt['status'] != 'failed' or receipt['stage'] != 'dependencies'
            or receipt['config_sha256'] != cfg['original_config']['sha256']
            or receipt['source_sha256'] != cfg['frozen_preparer']['sha256']
            or review['import_check'] != 'not_started' or review['checkpoint'] != 'not_started'
            or review['native'] != 'not_started'):
        raise RecoveryFailure('Expected the specific pre-import preparation failure')
    overlay = {p.removeprefix('overlay/'): v for p, v in evidence['cache_inventory'].items() if p.startswith('overlay/')}
    if overlay != evidence['overlay_inventory']['files'] or len(overlay) != review['overlay_files']:
        raise RecoveryFailure('Archived overlay evidence disagrees')
    assets = [a for a in original['assets'] if a['kind'] != 'checkpoint']
    if len(receipt['assets']) != 8:
        raise RecoveryFailure('Eight verified dependency assets required')
    for asset, record in zip(assets, receipt['assets']):
        path = local(failed, asset['relative_path'])
        if (record['asset'] != asset or record['status'] != 'downloaded_verified'
                or record['payload_bytes_observed'] != asset['bytes']
                or path.stat().st_size != asset['bytes'] or sha(path) != asset['sha256']
                or record != json.loads(local(failed, 'asset-records/' + asset['id'] + '.json').read_text())):
            raise RecoveryFailure('Dependency asset/record differs')
    install = json.loads(local(failed, 'install.json').read_text())
    if (install != receipt['installation'] or install['exit_code'] != 0
            or install['raw_wait_status'] != 0 or install.get('terminated_by_parent')):
        raise RecoveryFailure('The preserved installation did not succeed')
    for stream in ('stdout', 'stderr'):
        if sha(local(failed, 'install.' + stream + '.log')) != install[stream + '_sha256']:
            raise RecoveryFailure('Preserved installation log differs')
    ledger_path = local(failed, 'acquisition-ledger.json')
    if (sha(ledger_path) != sha(local(failed, 'acquisition-ledger-dependencies.json'))
            or sha(ledger_path) != receipt['ledger_snapshot']['sha256']):
        raise RecoveryFailure('Prior acquisition ledger differs')
    ledger = json.loads(ledger_path.read_text())
    if (ledger['payload_bytes_observed'] != review['actual_new_asset_payload_bytes']
            or ledger['conservative_cumulative_ceiling_bytes'] != review['conservative_cumulative_ceiling_bytes']):
        raise RecoveryFailure('Prior acquisition accounting differs')
    return assets, ledger


def copy_sources(failed, source, assets):
    """Exclusive byte copies; source files are closed before verification."""
    source.mkdir(exist_ok=False)
    result = {}
    for asset in assets:
        if asset['kind'] != 'source':
            continue
        rel = asset['relative_path'].removeprefix('source/')
        src = local(failed, asset['relative_path']); dst = local(source, rel)
        if src.stat().st_size != asset['bytes'] or sha(src) != asset['sha256']:
            raise RecoveryFailure('Source changed before copy')
        dst.parent.mkdir(parents=True, exist_ok=True)
        with src.open('rb') as inp, dst.open('xb') as out:
            while block := inp.read(1024 * 1024):
                out.write(block)
            out.flush(); os.fsync(out.fileno())
        if dst.stat().st_size != asset['bytes'] or sha(dst) != asset['sha256']:
            raise RecoveryFailure('Closed source copy failed verification')
        result[rel] = {'bytes': asset['bytes'], 'sha256': asset['sha256']}
    if len(result) != 5 or inventory(source) != result:
        raise RecoveryFailure('Expected exactly five clean source copies')
    return result


def verify_manifest(root, reference, directory, config_sha, source_sha):
    path = local(root, reference['relative_path'])
    if sha(path) != reference['sha256']:
        raise RecoveryFailure('Recovery manifest changed')
    manifest = json.loads(path.read_text())
    if (manifest['config_sha256'] != config_sha or manifest['source_sha256'] != source_sha
            or manifest['files'] != inventory(directory)):
        raise RecoveryFailure('Recovered files differ from manifest')
    return manifest


def inherited_ledger(prior, prior_digest, config_sha, source_sha):
    ledger = copy.deepcopy(prior)
    ledger.update(inherited_ledger_sha256=prior_digest,
                  prior_config_sha256=prior['config_sha256'], prior_source_sha256=prior['source_sha256'],
                  config_sha256=config_sha, source_sha256=source_sha, new_payload_bytes_observed=0)
    return ledger


def checkpoint_once(asset, root, ledger, helper, transfer, open_url=None):
    """One new GET only; close the partial before publishing it. Never retry."""
    final = local(root, asset['relative_path']); partial = final.with_name(final.name + '.partial')
    record_path = local(root, 'asset-records/' + asset['id'] + '.json')
    if any(p.exists() or p.is_symlink() for p in (final, partial, record_path)):
        raise RecoveryFailure('Existing checkpoint attempt must be preserved, not retried')
    if asset['id'] in ledger['reservations']:
        raise RecoveryFailure('Checkpoint was already reserved')
    ceiling = ledger['conservative_cumulative_ceiling_bytes'] + asset['bytes'] + 1
    if ceiling > ledger['limit_bytes'] or ceiling != ledger['planned_ceiling_bytes']:
        raise RecoveryFailure('Checkpoint exceeds the frozen cumulative budget')
    final.parent.mkdir(parents=True, exist_ok=True); record_path.parent.mkdir(parents=True, exist_ok=True)
    record = {'asset': asset, 'status': 'starting', 'started_utc': helper.utc(),
              'config_sha256': ledger['config_sha256'], 'source_sha256': ledger['source_sha256'],
              'http_payload_attempts': 0, 'payload_bytes_observed': 0}
    helper.save(record_path, record, exclusive=True)
    ledger['reservations'][asset['id']] = asset['bytes'] + 1
    ledger['conservative_cumulative_ceiling_bytes'] = ceiling
    helper.save(root/'acquisition-ledger.json', ledger)
    start = time.monotonic(); digest = hashlib.sha256()
    try:
        record['http_payload_attempts'] = 1; helper.save(record_path, record)
        with helper.deadline(transfer['per_asset_timeout_seconds']):
            with partial.open('xb') as out:
                with (open_url or helper.default_open)(asset['url'], timeout=transfer['read_timeout_seconds']) as response:
                    if response.status != 200:
                        raise RecoveryFailure('Unexpected HTTP status')
                    length = response.headers.get('Content-Length')
                    if length is not None and int(length) != asset['bytes']:
                        raise RecoveryFailure('Checkpoint Content-Length differs')
                    record.update(http_status=200, response_content_length=length,
                                  final_https_host=urllib.parse.urlsplit(response.geturl()).hostname)
                    while True:
                        remaining = asset['bytes'] + 1 - record['payload_bytes_observed']
                        block = response.read(min(transfer['chunk_bytes'], remaining))
                        if not block:
                            break
                        record['payload_bytes_observed'] += len(block)
                        ledger['payload_bytes_observed'] += len(block)
                        ledger['new_payload_bytes_observed'] += len(block)
                        digest.update(block); out.write(block); out.flush()
                        helper.save(root/'acquisition-ledger.json', ledger); helper.save(record_path, record)
                        if record['payload_bytes_observed'] > asset['bytes']:
                            raise RecoveryFailure('Checkpoint exceeds frozen length; one sentinel byte retained')
                out.flush(); os.fsync(out.fileno())
            # Unlike v1, no link or unlink occurs while the payload stream is open.
            if (partial.stat().st_size != asset['bytes'] or sha(partial) != asset['sha256']
                    or digest.hexdigest() != asset['sha256']):
                raise RecoveryFailure('Closed checkpoint partial failed length/hash verification')
            os.link(partial, final)
            partial.unlink()
            if partial.exists() or final.stat().st_size != asset['bytes'] or sha(final) != asset['sha256']:
                raise RecoveryFailure('Checkpoint publication state differs; preserve files')
        record.update(status='downloaded_verified', sha256=asset['sha256'])
    except BaseException as error:
        record.update(status='failed', error=error_record(helper,error))
        raise
    finally:
        record.update(finished_utc=helper.utc(), elapsed_seconds=time.monotonic()-start,
                      partial_bytes_stored=partial.stat().st_size if partial.exists() else 0,
                      partial_exists=partial.exists(), observed_payload_sha256=digest.hexdigest())
        helper.save(record_path, record)
    return record


def run_stage(repo, old, failed, root, config_path, config_sha, stage):
    if sha(config_path) != config_sha:
        raise RecoveryFailure('Recovery configuration SHA differs')
    cfg, original, helper, evidence = load_context(repo, json.loads(config_path.read_text()))
    if sys.platform != 'linux' or platform.python_version() != original['runtime']['python']:
        raise RecoveryFailure('Runtime differs from cloud preflight')
    affinity = [0, 1, 2, 3]
    if not set(affinity).issubset(os.sched_getaffinity(0)):
        raise RecoveryFailure('Frozen CPUs 0,1,2,3 unavailable')
    os.sched_setaffinity(0, affinity); resource.setrlimit(resource.RLIMIT_AS, (8*1024**3,)*2)
    old_hashes = check_old_runtime(old, original, evidence['failure_review'])
    assets, prior_ledger = verify_failed_cache(failed, cfg, original, evidence)
    if stage == 'dependencies':
        root.mkdir(exist_ok=False)
    elif not root.is_dir():
        raise RecoveryFailure('Recovery dependencies have not run')
    source_sha = sha(__file__)
    paths = {name: str(path) for name, path in [('old_cache',old),('failed_cache',failed),('recovery_root',root),('source_root',root/'source'),('overlay',failed/'overlay')]}
    with local(root, 'recovery.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        if local(root, '0005-recovered-native-started.json').exists():
            raise RecoveryFailure('A native attempt already exists; preparation must not run')
        marker = local(root, 'markers/' + stage + '.started.json')
        receipt_path = local(root, 'recovery-' + stage + '.json')
        if marker.exists() or receipt_path.exists():
            raise RecoveryFailure('Recovery stage already attempted')
        marker.parent.mkdir(exist_ok=True)
        receipt = {'schema_version':1, 'stage':stage+'-recovery', 'status':'running',
                   'config_sha256':config_sha, 'source_sha256':source_sha,
                   'original_config_sha256':cfg['original_config']['sha256'],
                   'frozen_preparer_sha256':cfg['frozen_preparer']['sha256'],
                   'prior_failure_receipt_sha256':cfg['evidence']['failure_receipt']['sha256'],
                   'prior_cache_inventory_sha256':cfg['evidence']['cache_inventory']['sha256'],
                   'prior_overlay_inventory_sha256':cfg['evidence']['overlay_inventory']['sha256'],
                   'checkout_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),
                   'started_utc':helper.utc(), 'paths':paths, 'affinity':affinity, 'AS_bytes':8*1024**3,
                   'new_network_payload_bytes':0, 'model_constructed':False, 'old_preservation':old_hashes}
        helper.save(marker,{**receipt,'pid':os.getpid()},exclusive=True)
        receipt['marker_sha256']=sha(marker); helper.save(receipt_path,receipt,exclusive=True)
        source_files={a['relative_path'].removeprefix('source/'):a['sha256'] for a in assets if a['kind']=='source'}
        sys.path[:]=[str(root/'source'),str(failed/'overlay')]+[p for p in sys.path if str(Path(p).resolve()) not in {str(root/'source'),str(failed/'overlay'),str(failed/'source')}]
        ledger = None
        try:
            if stage == 'dependencies':
                ledger=inherited_ledger(prior_ledger,sha(failed/'acquisition-ledger.json'),config_sha,source_sha)
                helper.save(root/'acquisition-ledger.json',ledger,exclusive=True)
                source_manifest=copy_sources(failed,root/'source',assets)
                helper.verify_source_tree(root/'source',source_files)
                overlay_manifest=helper.file_manifest(failed/'overlay')
                if overlay_manifest != evidence['overlay_inventory']['files']:
                    raise RecoveryFailure('Installed overlay differs before import')
                temporary=root/'tmp';temporary.mkdir(exist_ok=False)
                env={'PATH':os.environ['PATH'],'PYTHONDONTWRITEBYTECODE':'1','PYTHONNOUSERSITE':'1','TMPDIR':str(temporary),
                     'PYTHONPATH':':'.join(map(str,[failed/'overlay',old/'runtime-fixed',old/'runtime',root/'source']))}
                for name in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','VECLIB_MAXIMUM_THREADS','NUMEXPR_NUM_THREADS'):
                    env[name]='4'
                pins={**original['runtime']['old_packages'],**original['runtime']['overlay_packages']}
                command=[sys.executable,'-c',helper.PROBE,str(old),str(failed/'overlay'),str(root/'source'),json.dumps(pins),json.dumps(source_files),str(local(repo,cfg['frozen_preparer']['path'])),cfg['frozen_preparer']['sha256']]
                receipt['import_check']=helper.child(command,root/'import-check',env,original['import_timeout_seconds'])
                probe=json.loads((root/'import-check.stdout.log').read_text())
                if probe['status']!='passed' or probe['no_model_constructed_or_forward_called'] is not True:
                    raise RecoveryFailure('Import-only probe did not report success')
                helper.verify_source_tree(root/'source',source_files)
                if inventory(root/'source')!=source_manifest or helper.file_manifest(failed/'overlay')!=overlay_manifest:
                    raise RecoveryFailure('Source/overlay changed during import')
                for name,files in [('source',source_manifest),('overlay',overlay_manifest)]:
                    path=root/(name+'-manifest.json')
                    helper.save(path,{'schema_version':1,'config_sha256':config_sha,'source_sha256':source_sha,'files':files},exclusive=True)
                    receipt[name+'_manifest']={'relative_path':path.name,'sha256':sha(path)}
                receipt['assets']=[{k:a[k] for k in ('id','relative_path','bytes','sha256')}|{'reused_verified':True} for a in assets]
                receipt['checkpoint_started']=False
            else:
                deps_path=root/'recovery-dependencies.json';deps=json.loads(deps_path.read_text())
                if (deps['status']!='completed' or deps['config_sha256']!=config_sha or deps['source_sha256']!=source_sha
                        or deps['paths']!=paths or deps['preserved_failed_cache'] is not True):
                    raise RecoveryFailure('Successful bound recovery dependency receipt required')
                if sha(local(root,'markers/dependencies.started.json'))!=deps['marker_sha256']:
                    raise RecoveryFailure('Recovery dependency marker changed')
                for name,directory in [('source',root/'source'),('overlay',failed/'overlay')]:
                    verify_manifest(root,deps[name+'_manifest'],directory,config_sha,source_sha)
                    receipt[name+'_manifest']=deps[name+'_manifest']
                helper.verify_source_tree(root/'source',source_files)
                child=json.loads((root/'import-check.json').read_text())
                if child!=deps['import_check'] or child['exit_code']!=0 or child['raw_wait_status']!=0 or child.get('terminated_by_parent'):
                    raise RecoveryFailure('Prior import child was not successful')
                for stream in ('stdout','stderr'):
                    if sha(root/('import-check.'+stream+'.log'))!=child[stream+'_sha256']:
                        raise RecoveryFailure('Prior import log changed')
                ledger_path=root/'acquisition-ledger.json'
                snapshot=local(root,deps['ledger_snapshot']['relative_path'])
                if (snapshot.name!='acquisition-ledger-dependencies.json'
                        or sha(ledger_path)!=deps['ledger_snapshot']['sha256'] or sha(snapshot)!=sha(ledger_path)):
                    raise RecoveryFailure('Recovery dependency ledger changed')
                ledger=json.loads(ledger_path.read_text())
                expected=inherited_ledger(prior_ledger,sha(failed/'acquisition-ledger.json'),config_sha,source_sha)
                if ledger!=expected:
                    raise RecoveryFailure('Recovery inherited ledger fields differ')
                receipt['dependency_receipt_sha256']=sha(deps_path)
                asset=next(a for a in original['assets'] if a['kind']=='checkpoint')
                receipt['checkpoint_asset']=checkpoint_once(asset,root,ledger,helper,original['transfer'])
                receipt['checkpoint_asset_record_sha256']=sha(root/('asset-records/'+asset['id']+'.json'))
                receipt['checkpoint_started']=True
            receipt['status']='completed'
        except BaseException as error:
            receipt.update(status='failed',error=error_record(helper,error))
        finally:
            try:
                verify_failed_cache(failed,cfg,original,evidence)
                check_old_runtime(old,original,evidence['failure_review'])
                receipt['preserved_failed_cache']=True
            except BaseException as error:
                receipt.update(status='failed',preserved_failed_cache=False,preservation_error=error_record(helper,error))
            if ledger is not None:
                receipt['new_network_payload_bytes']=ledger['new_payload_bytes_observed']
                snapshot=root/('acquisition-ledger-'+stage+'.json')
                helper.save(snapshot,ledger,exclusive=True)
                receipt['ledger_snapshot']={'relative_path':snapshot.name,'sha256':sha(snapshot)}
            receipt['finished_utc']=helper.utc();helper.save(receipt_path,receipt)
        print(json.dumps({'status':receipt['status'],'stage':stage,'receipt':str(receipt_path)},indent=2))
        return 0 if receipt['status']=='completed' else 1


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    for name in ('config','config-sha256','old-cache','failed-cache','recovery-root','stage'):
        parser.add_argument('--'+name,required=True)
    parser.add_argument('--repository',default=os.getcwd());args=parser.parse_args()
    if args.stage not in ('dependencies','checkpoint'):
        raise RecoveryFailure('Unknown recovery stage')
    def interrupted(signum,frame):
        raise TimeoutError('External recovery deadline')
    signal.signal(signal.SIGTERM,interrupted)
    paths=[]
    for name in ('old_cache','failed_cache','recovery_root'):
        original=Path(getattr(args,name)).absolute()
        if original.is_symlink():
            raise RecoveryFailure('Cache root is a symlink')
        paths.append(original.resolve())
    old,failed,root=paths
    if len(set(paths))!=3 or len({p.parent for p in paths})!=1:
        raise RecoveryFailure('Old, failed and recovery caches must be distinct siblings')
    return run_stage(Path(args.repository).resolve(),old,failed,root,Path(args.config).resolve(),args.config_sha256,args.stage)


if __name__=='__main__':
    raise SystemExit(main())
